from pypdf import PdfReader
reader = PdfReader('/app/paper.pdf')
terms=['decoder','decoding','decode score','reward-relative position','circular–linear regression','circular-linear regression']
for pageno,page in enumerate(reader.pages, start=1):
    try:
        text = page.extract_text() or ''
    except Exception as e:
        print('PAGE',pageno,'ERROR',e)
        continue
    lower=text.lower()
    hits=[]
    for term in terms:
        if term.lower() in lower:
            hits.append(term)
    if hits:
        print(f'=== PAGE {pageno} HITS {hits} ===')
        for term in hits:
            idx=0
            t=term.lower()
            while True:
                i=lower.find(t, idx)
                if i==-1: break
                start=max(0,i-200)
                end=min(len(text),i+300)
                snippet=text[start:end].replace('\n',' ')
                print(snippet)
                print()
                idx=i+len(t)
